<?php

declare(strict_types=1);

namespace Tests\Unit\Util;

use AA\Util\ScriptTag;
use PHPUnit\Framework\TestCase;

/**
 * ScriptTag generates the <script>/<link> tags for the page head and the
 * loader snippets used when a form arrives over AJAX.
 *
 * The two paths used to be generated by separate inline code in AA_Req_Lib /
 * AA_Req_Css, and the AJAX one silently dropped both the loadtype and the SRI
 * hash - so an ESM library loaded from the head but not inside an AJAX-rendered
 * form. These tests pin both paths to the same inputs.
 */
final class ScriptTagTest extends TestCase
{
    /** Literal backslash, spelled this way so the escape sequences below stay readable. */
    private const BS = "\\";

    // --- head() ---------------------------------------------------------

    public function test_head_emits_plain_script(): void
    {
        self::assertSame(
            '<script src="https://cdn/x.js"></script>',
            ScriptTag::head('https://cdn/x.js'),
        );
    }

    public function test_head_adds_integrity_and_crossorigin(): void
    {
        self::assertSame(
            '<script src="https://cdn/x.js" integrity="sha256-abc" crossorigin="anonymous"></script>',
            ScriptTag::head('https://cdn/x.js', 'sha256-abc'),
        );
    }

    public function test_head_module_loadtype_emits_type_module(): void
    {
        self::assertSame(
            '<script type="module" src="https://cdn/x.js"></script>',
            ScriptTag::head('https://cdn/x.js', '', 'module'),
        );
    }

    public function test_head_defer_loadtype_emits_bare_attribute(): void
    {
        self::assertSame(
            '<script defer src="https://cdn/x.js"></script>',
            ScriptTag::head('https://cdn/x.js', '', 'defer'),
        );
    }

    public function test_head_returns_empty_string_for_empty_url(): void
    {
        self::assertSame('', ScriptTag::head(''));
    }

    public function test_head_escapes_the_url(): void
    {
        self::assertSame(
            '<script src="https://x/y.js?a=&quot;&gt;&lt;script&gt;"></script>',
            ScriptTag::head('https://x/y.js?a="><script>'),
        );
    }

    // --- ajaxJs() -------------------------------------------------------

    /** Regression: the AJAX path used to drop loadtype and integrity entirely. */
    public function test_ajaxJs_passes_module_type_and_integrity(): void
    {
        self::assertSame(
            'AA_LoadJs(\'load_once\',AA_IsLoaded,\'https://cdn/x.js\',true,'
                . '{"type":"module","integrity":"sha256-abc"});',
            ScriptTag::ajaxJs('https://cdn/x.js', 'sha256-abc', 'module'),
        );
    }

    public function test_ajaxJs_without_options_omits_options_argument(): void
    {
        self::assertSame(
            'AA_LoadJs(\'load_once\',AA_IsLoaded,\'https://cdn/x.js\',true);',
            ScriptTag::ajaxJs('https://cdn/x.js'),
        );
    }

    public function test_ajaxJs_emits_integrity_without_module(): void
    {
        self::assertSame(
            'AA_LoadJs(\'load_once\',AA_IsLoaded,\'https://cdn/x.js\',true,{"integrity":"sha256-abc"});',
            ScriptTag::ajaxJs('https://cdn/x.js', 'sha256-abc'),
        );
    }

    public function test_ajaxJs_returns_empty_string_for_blank_url(): void
    {
        self::assertSame('', ScriptTag::ajaxJs('   '));
    }

    /** The snippet is emitted inside a <script> block, so nothing from the URL
     *  may close the JS string literal. */
    public function test_ajaxJs_escapes_apostrophe_in_url(): void
    {
        $out = ScriptTag::ajaxJs('https://cdn/x' . "'" . '.js');

        self::assertSame(
            'AA_LoadJs(\'load_once\',AA_IsLoaded,\'https://cdn/x' . self::BS . 'u0027.js\',true);',
            $out,
        );
        // Four apostrophes: the delimiters of 'load_once' and of the URL. A raw
        // one from the URL would make a fifth and break the literal.
        self::assertSame(4, substr_count($out, "'"));
    }

    /** A double quote must not reach the literal raw either - the JSON delimiters
     *  are sliced off, never trimmed, so no escape can be eaten. */
    public function test_ajaxJs_escapes_double_quote_in_url(): void
    {
        $out = ScriptTag::ajaxJs('https://cdn/x"');

        self::assertSame(
            'AA_LoadJs(\'load_once\',AA_IsLoaded,\'https://cdn/x' . self::BS . 'u0022\',true);',
            $out,
        );
        self::assertStringNotContainsString(self::BS . '\',true);', $out);
    }

    public function test_ajaxJs_escapes_closing_script_tag_in_url(): void
    {
        $out = ScriptTag::ajaxJs('https://cdn/x</script>.js');

        self::assertStringNotContainsString('</script>', $out);
        self::assertStringContainsString(self::BS . 'u003C', $out);
    }

    // --- css() / ajaxCss() ----------------------------------------------

    public function test_css_emits_stylesheet_link(): void
    {
        self::assertSame(
            '<link rel="stylesheet" href="https://cdn/x.css">',
            ScriptTag::css('https://cdn/x.css'),
        );
    }

    public function test_css_adds_integrity(): void
    {
        self::assertSame(
            '<link rel="stylesheet" href="https://cdn/x.css" integrity="sha256-abc" crossorigin="anonymous">',
            ScriptTag::css('https://cdn/x.css', 'sha256-abc'),
        );
    }

    public function test_css_async_uses_media_print_onload_trick(): void
    {
        self::assertSame(
            '<link rel="stylesheet" href="https://cdn/x.css" media="print" onload="this.media=\'all\'">',
            ScriptTag::css('https://cdn/x.css', '', 'async'),
        );
    }

    public function test_css_named_loadtype_becomes_media_attribute(): void
    {
        self::assertSame(
            '<link rel="stylesheet" href="https://cdn/x.css" media="print">',
            ScriptTag::css('https://cdn/x.css', '', 'print'),
        );
    }

    public function test_ajaxCss_skips_print_loadtype(): void
    {
        self::assertSame('', ScriptTag::ajaxCss('https://cdn/x.css', 'print'));
    }

    public function test_ajaxCss_emits_loader_call(): void
    {
        self::assertSame(
            'AA_LoadCss(\'https://cdn/x.css\');',
            ScriptTag::ajaxCss('https://cdn/x.css'),
        );
    }
}
